    let out = bin().arg("-n").arg("0").output().expect("run ulidgen -n 0");
    assert!(out.status.success(), "exit status must be 0 on success");
    assert_eq!(String::from_utf8_lossy(&out.stdout), "", "-n 0 prints nothing");
}

